import json
import gzip
import base64
from typing import Any, Dict, Tuple, Union
import re

class CapFoxCrypt:
    def __init__(self):
        self.prefix = b"\x01\x04"

    @staticmethod
    def json_to_byte(json_data: dict) -> bytes:
        return json.dumps(json_data, separators=(",", ":")).encode("utf-8")

    @staticmethod
    def gzip_compress(b_data: bytes) -> bytes:
        return gzip.compress(b_data)

    @staticmethod
    def encoder_to_b64(b_data: bytes) -> str:
        return base64.b64encode(b_data).decode()

    @staticmethod
    def encoder_to_hex(b_data: bytes) -> str:
        return b_data.hex()

    def encoder(self, payload_json: dict) -> bytes:
        p_bytes = CapFoxCrypt.json_to_byte(payload_json)
        gzip_comp_bytes = CapFoxCrypt.gzip_compress(p_bytes)
        encoded = bytearray(self.prefix)
        for index, byte in enumerate(gzip_comp_bytes):
            encoded.append(byte ^ ((index + 4) & 0xFF))
        return bytes(encoded)

    def decoder(self,encode_payload: Union[str, bytes, bytearray]) -> Dict[str, Any]:
        if isinstance(encode_payload, str):
            try:
                data = bytes.fromhex(encode_payload)
            except ValueError:
                data = base64.b64decode(encode_payload)
        else:
            data = bytes(encode_payload)

        if not data.startswith(self.prefix):
            raise ValueError("Invalid payload: prefix mismatch")
        encrypted_data = data[len(self.prefix):]

        gzip_comp_bytes = bytearray()
        for index, byte in enumerate(encrypted_data):
            gzip_comp_bytes.append(byte ^ ((index + 4) & 0xFF))

        try:
            json_bytes = gzip.decompress(bytes(gzip_comp_bytes))
        except gzip.BadGzipFile:
            raise ValueError("Decryption failed or data corrupted: invalid gzip stream")

        return json.loads(json_bytes.decode("utf-8"))

if __name__ == '__main__':
    cap_cry = CapFoxCrypt()
